  "name" text   NOT NULL,
  CONSTRAINT "class_status_options_name_key1" UNIQUE (name),
  CONSTRAINT "class_status_options_pkey1" PRIMARY KEY (id)
);

ALTER TABLE "public"."status"
  ENABLE ROW LEVEL SECURITY;

ALTER TABLE "public"."sessions"
  ADD COLUMN "backUp" text;

