CREATE POLICY "Allow public session reads" ON "public"."sessions"
  FOR SELECT
  TO "anon"
  USING (true);

CREATE POLICY "Allow public session updates" ON "public"."sessions"
  FOR UPDATE
  TO "anon"
  USING (true)
  WITH CHECK (true);

CREATE POLICY "Allow public read" ON "public"."status"
  FOR SELECT
  TO "anon"
  USING (true);

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."status" TO "anon", "authenticated", "postgres", "service_role";

